window.BANK=window.BANK||{};window.BANK["7938"]={"n":"第四章单选 明确价值要求 践行价值准则","qs":[{"i":"162563","t":"单选","q":"富强、民主、文明、和谐，这一价值追求回答了我们","o":{"A":"A.要建设什么样的国家的重大问题","B":"B.要建设什么样的社会的重大问题","C":"C.要建设什么样的政府的重大问题","D":"D.要培育什么样的公民的重大问题"},"a":"A","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P299考点24表格</span></p>\n<p><img src=\"https://cangdun.oss-cn-beijing.aliyuncs.com/cdky/cdkyzz/202607/30/72CE070E141176E6E5150E67457B7F2B.blob\" alt=\"\" /></p>\n<p><strong>简析：</strong>富强、民主、文明、和谐的价值追求回答了我们要建设什么样的国家的重大问题，揭示了当代中国经济社会发展的价值目标，从国家层面标注了社会主义核心价值观的时代刻度。A正确，B、C、D错误。点拨核心价值观的24个字，分3组分别在国家层面、社会层面、公民层面回答了我们要建设什么样的国家、建设什么样的社会、培育什么样的公民的重大问题。</p>","k":"考点20 社会主义核心价值观和社会主义核心价值体系","kid":"386","r":340,"tot":403},{"i":"162564","t":"单选","q":"自由、平等、公正、法治，这一价值追求回答了我们要建设什么样的社会的重大问题，反映了人们对美好社会的期望和憧憬，是","o":{"A":"A.衡量现代社会是否高度发展、充满活力、和谐有序的重要标志","B":"B.判断社会性质的主要标准","C":"C.社会进步的根本内容","D":"D.衡量社会进步的根本尺度"},"a":"A","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P299考点24表格</strong></span></p>\n<p><span style=\"color: #000000;\"><img src=\"data:image/png;base64,\" alt=\"\" /></span></p>\n<p><span style=\"color: #000000;\">简析：自由、平等、公正、法治，反映了人们对美好社会的期望和憧憬，是衡量现代社会是否高度发展、充满活力、和谐有序的重要标志。A正确。判断社会性质的主要标准是生产关系的性质；生产力是社会进步的根本内容，也是衡量社会进步的根本尺度。B、C、D错误。</span></p>","k":"考点20 社会主义核心价值观和社会主义核心价值体系","kid":"386","r":345,"tot":394},{"i":"162566","t":"单选","q":"社会主义核心价值观的根本特性是","o":{"A":"A.先进性","B":"B.人民性","C":"C.普适性","D":"D.真实性"},"a":"B","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P300考点27</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>考点27彰显人民至上的价值立场(人民性)重要</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>人民性是社会主义核心价值观的根本特性。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1尊重人民群众历史主体地位。</strong>人民至上是社会主义核心价值观鲜明的价值立场。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2. 体现以人民为中心的价值导向。</strong>鲜明的人民性使得社会主义核心价值观具有强大的感召力。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>人民性是社会主义核心价值观的根本特性。B正确，A、D不符合题意。C错误。</p>","k":"考点22 社会主义核心价值观的显著特征","kid":"388","r":305,"tot":393},{"i":"162567","t":"单选","q":"社会主义核心价值观的先进性集中体现在","o":{"A":"A.它是社会主义所坚持和追求的价值理念","B":"B.它吸纳了世界文明有益成果","C":"C.它是真切、具体、广泛的现实","D":"D.它扎根于中华优秀传统文化土壤"},"a":"A","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P300考点26-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1体现社会主义的本质属性。</strong>社会主义核心价值观的先进性，集中体现在它是社会主义所坚持和追求的价值理念。社会主义核心价值观是我国社会主义制度的内在精神之魂，是中国特色社会主义本质规定的价值表达。</span></p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>","k":"考点22 社会主义核心价值观的显著特征","kid":"388","r":276,"tot":396}]};
